package com.example.workout.workout.mapper;
import com.example.workout.generated.model.WorkoutPatchRequest; import com.example.workout.workout.model.*; import java.util.*; import java.util.function.Consumer; import org.openapitools.jackson.nullable.JsonNullable;
public final class WorkoutPatchMapper { private WorkoutPatchMapper(){throw new UnsupportedOperationException("This class should never be instantiated");}
 public static Result toModel(WorkoutPatchRequest dto){Workout w=new Workout();Set<String> f=new HashSet<>();copy("workoutDate",dto.getWorkoutDate(),f,w::setWorkoutDate);copy("name",dto.getName(),f,w::setName);copy("description",dto.getDescription(),f,w::setDescription);copy("notes",dto.getNotes(),f,w::setNotes);copy("distanceMeters",dto.getDistanceMeters(),f,w::setDistanceMeters);copy("durationSeconds",dto.getDurationSeconds(),f,w::setDurationSeconds);copy("movingTimeSeconds",dto.getMovingTimeSeconds(),f,w::setMovingTimeSeconds);copy("averagePaceSecondsPerKm",dto.getAveragePaceSecondsPerKm(),f,w::setAveragePaceSecondsPerKm);copy("bestPaceSecondsPerKm",dto.getBestPaceSecondsPerKm(),f,w::setBestPaceSecondsPerKm);copy("averageHeartRate",dto.getAverageHeartRate(),f,w::setAverageHeartRate);copy("maxHeartRate",dto.getMaxHeartRate(),f,w::setMaxHeartRate);copy("averageCadence",dto.getAverageCadence(),f,w::setAverageCadence);copy("maxCadence",dto.getMaxCadence(),f,w::setMaxCadence);copy("averagePowerWatts",dto.getAveragePowerWatts(),f,w::setAveragePowerWatts);copy("maxPowerWatts",dto.getMaxPowerWatts(),f,w::setMaxPowerWatts);copy("elevationGainMeters",dto.getElevationGainMeters(),f,w::setElevationGainMeters);copy("elevationLossMeters",dto.getElevationLossMeters(),f,w::setElevationLossMeters);copy("minimumElevationMeters",dto.getMinimumElevationMeters(),f,w::setMinimumElevationMeters);copy("maximumElevationMeters",dto.getMaximumElevationMeters(),f,w::setMaximumElevationMeters);copy("calories",dto.getCalories(),f,w::setCalories);copy("averageStrideLengthMeters",dto.getAverageStrideLengthMeters(),f,w::setAverageStrideLengthMeters);copy("verticalOscillationCm",dto.getVerticalOscillationCm(),f,w::setVerticalOscillationCm);copy("groundContactTimeMs",dto.getGroundContactTimeMs(),f,w::setGroundContactTimeMs);copy("perceivedEffort",dto.getPerceivedEffort(),f,w::setPerceivedEffort);copy("completed",dto.getCompleted(),f,w::setCompleted);copy("temperatureCelsius",dto.getTemperatureCelsius(),f,w::setTemperatureCelsius);copy("humidityPercent",dto.getHumidityPercent(),f,w::setHumidityPercent);copy("windSpeedKph",dto.getWindSpeedKph(),f,w::setWindSpeedKph);copy("weather",dto.getWeather(),f,w::setWeather);copy("location",dto.getLocation(),f,w::setLocation);copy("routeName",dto.getRouteName(),f,w::setRouteName);copy("externalActivityId",dto.getExternalActivityId(),f,w::setExternalActivityId);copy("shoeId",dto.getShoeId(),f,w::setShoeId);copy("workoutType",dto.getWorkoutType(),f,v->w.setWorkoutType(v==null?null:WorkoutType.valueOf(v.getValue())));copy("feeling",dto.getFeeling(),f,v->w.setFeeling(v==null?null:WorkoutFeeling.valueOf(v.getValue())));copy("source",dto.getSource(),f,v->w.setSource(v==null?null:WorkoutSource.valueOf(v.getValue())));if(present(dto.getSegments())){f.add("segments");var v=dto.getSegments().orElse(null);w.setSegments(v==null?null:v.stream().map(WorkoutMapperAccess::segment).toList());}if(present(dto.getLaps())){f.add("laps");var v=dto.getLaps().orElse(null);w.setLaps(v==null?null:v.stream().map(WorkoutMapperAccess::lap).toList());}if(present(dto.getTrackPoints())){f.add("trackPoints");var v=dto.getTrackPoints().orElse(null);w.setTrackPoints(v==null?null:v.stream().map(WorkoutMapperAccess::point).toList());}return new Result(w,new WorkoutPatchPresence(f));}
 private static <T> void copy(String n,JsonNullable<T> v,Set<String> f,Consumer<T> c){if(present(v)){f.add(n);c.accept(v.orElse(null));}} private static boolean present(JsonNullable<?> v){return v!=null&&v.isPresent();} public record Result(Workout workout,WorkoutPatchPresence presence){}
}
